class Provider {
  getSettings() {
    return { supportsMultiScanlator: true, supportsMultiLanguage: true };
  }

  async search(options) {
    return [{
      provider: "phase5-local-manga-proof",
      id: "phase5-local-manga",
      title: options.query || "Phase 5 Local Manga",
      image: "http://127.0.0.1:18846/phase5-cover.jpg",
      searchRating: 1
    }];
  }

  async findChapters(id) {
    return [
      {
        provider: "phase5-local-manga-proof",
        id: id + "$chapter-2$ja",
        url: "http://127.0.0.1:18846/manga/" + id + "/2",
        title: "Chapter 2 - \u7b2c\u4e8c\u8a71",
        chapter: "2",
        index: 1,
        scanlator: "Phase5 Group",
        language: "ja"
      },
      {
        provider: "phase5-local-manga-proof",
        id: id + "$chapter-1$ja",
        url: "http://127.0.0.1:18846/manga/" + id + "/1",
        title: "Chapter 1 - \u7b2c\u4e00\u8a71",
        chapter: "1",
        index: 0,
        scanlator: "Phase5 Group",
        language: "ja"
      }
    ];
  }

  async findChapterPages(id) {
    return [
      {
        provider: "phase5-local-manga-proof",
        url: "http://127.0.0.1:18846/manga/" + id + "/page-2.jpg",
        index: 1,
        headers: { "X-Phase5-Proof": "manga-page-header" }
      },
      {
        provider: "phase5-local-manga-proof",
        url: "http://127.0.0.1:18846/manga/" + id + "/page-1.jpg",
        index: 0,
        headers: { "X-Phase5-Proof": "manga-page-header" }
      }
    ];
  }
}
